# Reflect more targeted
cat > Program.cs.tmp << 'CSHARP'
using System.Reflection;
using Microsoft.Agents.AI;

// ChatClientAgent
var t = typeof(ChatClientAgent);
Console.WriteLine($"=== {t.FullName} (base: {t.BaseType?.Name}) ===");
foreach (var c in t.GetConstructors())
    Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})");
foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.FlattenHierarchy))
    Console.WriteLine($"  prop {p.Name}: {p.PropertyType}");
foreach (var m in t.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.FlattenHierarchy).Where(m => !m.IsSpecialName))
    Console.WriteLine($"  {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})");

// AgentRunOptions  
Console.WriteLine("\n=== AgentRunOptions ===");
var t2 = typeof(AgentRunOptions);
foreach (var p in t2.GetProperties())
    Console.WriteLine($"  prop {p.Name}: {p.PropertyType}");
foreach (var c in t2.GetConstructors())
    Console.WriteLine($"  ctor({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})");

// AIAgent
Console.WriteLine("\n=== AIAgent (abstract) ===");
var t3 = typeof(ChatClientAgent).BaseType!;
foreach (var m in t3.GetMethods(BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly).Where(m => !m.IsSpecialName))
    Console.WriteLine($"  {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})");
foreach (var p in t3.GetProperties())
    Console.WriteLine($"  prop {p.Name}: {p.PropertyType}");

// Check IAgent interface
Console.WriteLine("\n=== Interfaces ===");
foreach (var iface in t.GetInterfaces())
{
    Console.WriteLine($"  {iface.FullName}");
    foreach (var m in iface.GetMethods().Where(m => !m.IsSpecialName))
        Console.WriteLine($"    {m.Name}({string.Join(", ", m.GetParameters().Select(p => $"{p.ParameterType} {p.Name}"))})");
}

// AgentResponse
Console.WriteLine("\n=== AgentResponse ===");
var t4 = typeof(AgentResponse);
foreach (var p in t4.GetProperties())
    Console.WriteLine($"  prop {p.Name}: {p.PropertyType}");
CSHARP

