using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------
var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(notepad.SaveNote),
    AIFunctionFactory.Create(notepad.ReadNotes),
};

// ---------------------------------------------------------------------------
// Build the ChatClientAgent
// ---------------------------------------------------------------------------
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Use the web_search tool to find relevant information (make several searches with different queries).
        2. Use the save_note tool to record key findings as you go.
        3. After gathering enough information, use the read_notes tool to review everything you collected.
        4. Provide a well-structured summary of your findings to the user.
        Be thorough but concise. Cite sources where possible.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: tools,
    loggerFactory: null,
    services: null);

// ---------------------------------------------------------------------------
// Run the agent
// ---------------------------------------------------------------------------
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

var response = await agent.RunAsync(topic, session, runOptions);

Console.WriteLine("\n══════════════════════════════════════════════════════");
Console.WriteLine("  RESEARCH SUMMARY");
Console.WriteLine("══════════════════════════════════════════════════════\n");
Console.WriteLine(response.Text);
Console.WriteLine();

if (notepad.Notes.Count > 0)
{
    Console.WriteLine("──────────────────────────────────────────────────────");
    Console.WriteLine($"  📝 {notepad.Notes.Count} note(s) collected during research");
    Console.WriteLine("──────────────────────────────────────────────────────\n");
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing 2025-2026"
        : input;
}

// ═══════════════════════════════════════════════════════════════════════════
// Web Search Tool
// ═══════════════════════════════════════════════════════════════════════════
internal static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public static async Task<string> WebSearch(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseDuckDuckGoResults(html, maxResults);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");
            for (var i = 0; i < results.Count; i++)
            {
                var r = results[i];
                sb.AppendLine($"{i + 1}. {r.Title}");
                sb.AppendLine($"   URL: {r.Url}");
                sb.AppendLine($"   {r.Snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    // Kept internal for testability
    internal static async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
        => await WebSearch(query, maxResults);

    private static List<SearchResult> ParseDuckDuckGoResults(string html, int max)
    {
        var results = new List<SearchResult>();
        var pos = 0;

        while (results.Count < max)
        {
            // DuckDuckGo HTML results have class="result__a" for links
            var linkStart = html.IndexOf("class=\"result__a\"", pos, StringComparison.Ordinal);
            if (linkStart < 0) break;

            var href = ExtractAttribute(html, linkStart, "href");
            var title = ExtractInnerText(html, linkStart);

            // Find snippet (class="result__snippet")
            var snippetMarker = html.IndexOf("class=\"result__snippet\"", linkStart, StringComparison.Ordinal);
            var snippet = snippetMarker >= 0 ? ExtractInnerText(html, snippetMarker) : "";

            if (!string.IsNullOrWhiteSpace(title))
            {
                // DuckDuckGo wraps URLs in a redirect; extract the actual URL
                var actualUrl = ExtractActualUrl(href);
                results.Add(new SearchResult(
                    CleanHtml(title),
                    actualUrl,
                    CleanHtml(snippet)));
            }

            pos = linkStart + 1;
        }

        return results;
    }

    private static string ExtractAttribute(string html, int startFrom, string attr)
    {
        var search = attr + "=\"";
        var idx = html.LastIndexOf(search, startFrom, Math.Min(startFrom, 500), StringComparison.Ordinal);
        if (idx < 0)
        {
            idx = html.IndexOf(search, startFrom, StringComparison.Ordinal);
        }

        if (idx < 0) return "";

        var valStart = idx + search.Length;
        var valEnd = html.IndexOf('"', valStart);
        return valEnd < 0 ? "" : html[valStart..valEnd];
    }

    private static string ExtractInnerText(string html, int attrPos)
    {
        var tagClose = html.IndexOf('>', attrPos);
        if (tagClose < 0) return "";

        var contentStart = tagClose + 1;
        var contentEnd = html.IndexOf('<', contentStart);
        if (contentEnd < 0) return "";

        return html[contentStart..contentEnd].Trim();
    }

    private static string ExtractActualUrl(string href)
    {
        // DuckDuckGo redirects look like: //duckduckgo.com/l/?uddg=<encoded_url>&...
        const string marker = "uddg=";
        var idx = href.IndexOf(marker, StringComparison.Ordinal);
        if (idx >= 0)
        {
            var start = idx + marker.Length;
            var end = href.IndexOf('&', start);
            var encoded = end >= 0 ? href[start..end] : href[start..];
            return WebUtility.UrlDecode(encoded);
        }

        return href.StartsWith("//") ? "https:" + href : href;
    }

    private static string CleanHtml(string text)
    {
        // Strip remaining HTML tags
        var sb = new StringBuilder(text.Length);
        var inTag = false;
        foreach (var c in text)
        {
            switch (c)
            {
                case '<': inTag = true; break;
                case '>': inTag = false; break;
                default:
                    if (!inTag) sb.Append(c);
                    break;
            }
        }

        return WebUtility.HtmlDecode(sb.ToString().Trim());
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

// ═══════════════════════════════════════════════════════════════════════════
// Note-Taking Tool
// ═══════════════════════════════════════════════════════════════════════════
internal sealed class Notepad
{
    private readonly List<NoteEntry> _notes = [];

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("Detailed content of the note")] string content)
    {
        _notes.Add(new NoteEntry(title, content, DateTime.UtcNow));
        return $"Note saved: \"{title}\" (total notes: {_notes.Count})";
    }

    [Description("Read all saved research notes. Use this to review collected findings before writing a summary.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");

        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"[{i + 1}] {note.Title}");
            sb.AppendLine($"    {note.Content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    internal sealed record NoteEntry(string Title, string Content, DateTime SavedAt);
}

